59	// Cache to store the results of setupUser to avoid redundant network calls.
60	// The cache is keyed by the AuthClient instance. Inside each entry, we use
61	// another cache keyed by project ID to ensure correctness if environment changes.
62	let userDataCache = createCache<
63	  AuthClient,
64	  CacheService<string | undefined, Promise<UserData>>
65	>({
66	  storage: 'weakmap',
