82	/**
83	 * Sets up the user by loading their Code Assist configuration and onboarding if needed.
84	 *
85	 * Tier eligibility:
86	 * - FREE tier: Eligibility is determined by the Code Assist server response.
87	 * - STANDARD tier: User is always eligible if they have a valid project ID.
88	 *
89	 * If no valid project ID is available (from env var or server response):
90	 * - Surfaces ineligibility reasons for the FREE tier from the server.
91	 * - Throws ProjectIdRequiredError if no ineligibility reasons are available.
92	 *
93	 * Handles VALIDATION_REQUIRED via the optional validation handler, allowing
94	 * retry, auth change, or cancellation.
95	 *
96	 * @param client - The authenticated client to use for API calls
97	 * @param validationHandler - Optional handler for account validation flow
98	 * @returns The user's project ID, tier ID, and tier name
99	 * @throws {ValidationRequiredError} If account validation is required
100	 * @throws {ProjectIdRequiredError} If no project ID is available and required
101	 * @throws {ValidationCancelledError} If user cancels validation
102	 * @throws {ChangeAuthRequestedError} If user requests to change auth method
103	 */
104	export async function setupUser(
105	  client: AuthClient,
106	  validationHandler?: ValidationHandler,
107	  httpOptions: HttpOptions = {},
108	): Promise<UserData> {
109	  const projectId =
110	    process.env['GOOGLE_CLOUD_PROJECT'] ||
111	    process.env['GOOGLE_CLOUD_PROJECT_ID'] ||
112	    undefined;
113	
114	  const projectCache = userDataCache.getOrCreate(client, () =>
115	    createCache<string | undefined, Promise<UserData>>({
116	      storage: 'map',
117	      defaultTtl: 30000, // 30 seconds
118	    }),
119	  );
120	
121	  return projectCache.getOrCreate(projectId, () =>
122	    _doSetupUser(client, projectId, validationHandler, httpOptions),
123	  );
124	}
