127	 * Internal implementation of the user setup logic.
128	 */
129	async function _doSetupUser(
130	  client: AuthClient,
131	  projectId: string | undefined,
132	  validationHandler?: ValidationHandler,
133	  httpOptions: HttpOptions = {},
134	): Promise<UserData> {
135	  const caServer = new CodeAssistServer(
136	    client,
137	    projectId,
138	    httpOptions,
139	    '',
140	    undefined,
141	    undefined,
142	  );
143	  const coreClientMetadata: ClientMetadata = {
144	    ideType: 'IDE_UNSPECIFIED',
145	    platform: 'PLATFORM_UNSPECIFIED',
146	    pluginType: 'GEMINI',
147	  };
148	
149	  let loadRes: LoadCodeAssistResponse;
150	  while (true) {
151	    loadRes = await caServer.loadCodeAssist({
152	      cloudaicompanionProject: projectId,
153	      metadata: {
154	        ...coreClientMetadata,
155	        duetProject: projectId,
156	      },
157	    });
158	
159	    try {
160	      validateLoadCodeAssistResponse(loadRes);
161	      break;
162	    } catch (e) {
163	      if (e instanceof ValidationRequiredError && validationHandler) {
164	        const intent = await validationHandler(
165	          e.validationLink,
166	          e.validationDescription,
167	        );
168	        if (intent === 'verify') {
169	          continue;
170	        }
171	        if (intent === 'change_auth') {
172	          throw new ChangeAuthRequestedError();
173	        }
174	        throw new ValidationCancelledError();
175	      }
176	      throw e;
177	    }
178	  }
179	
180	  if (loadRes.currentTier) {
181	    if (!loadRes.paidTier?.id && !loadRes.currentTier.id) {
182	      debugLogger.warn(
183	        'Warning: Code Assist API did not return a user tier ID. Defaulting to STANDARD tier.',
184	      );
185	    }
186	
187	    if (!loadRes.cloudaicompanionProject) {
188	      if (projectId) {
189	        return {
190	          projectId,
191	          userTier:
192	            loadRes.paidTier?.id ??
193	            loadRes.currentTier.id ??
194	            UserTierId.STANDARD,
195	          userTierName: loadRes.paidTier?.name ?? loadRes.currentTier.name,
196	          paidTier: loadRes.paidTier ?? undefined,
197	        };
198	      }
199	
200	      // If user is not setup for standard tier, inform them about all other tiers they are ineligible for.
201	      throwIneligibleOrProjectIdError(loadRes);
202	    }
203	    return {
204	      projectId: loadRes.cloudaicompanionProject,
205	      userTier:
206	        loadRes.paidTier?.id ?? loadRes.currentTier.id ?? UserTierId.STANDARD,
207	      userTierName: loadRes.paidTier?.name ?? loadRes.currentTier.name,
208	      paidTier: loadRes.paidTier ?? undefined,
209	    };
210	  }
211	
212	  const tier = getOnboardTier(loadRes);
213	
214	  if (!tier.id) {
215	    debugLogger.warn(
216	      'Warning: Code Assist API did not return an onboarding tier ID. Defaulting to STANDARD tier.',
217	    );
218	  }
219	
220	  let onboardReq: OnboardUserRequest;
221	  if (tier.id === UserTierId.FREE) {
222	    // The free tier uses a managed google cloud project. Setting a project in the `onboardUser` request causes a `Precondition Failed` error.
223	    onboardReq = {
224	      tierId: tier.id,
225	      cloudaicompanionProject: undefined,
226	      metadata: coreClientMetadata,
227	    };
228	  } else {
229	    onboardReq = {
