96	  config: Config,
97	  event: StartSessionEvent,
98	): void {
99	  void ClearcutLogger.getInstance(config)?.logStartSessionEvent(event);
100	  bufferTelemetryEvent(() => {
101	    // Wait for experiments to load before emitting so we capture experimentIds
102	    void config
103	      .getExperimentsAsync()
104	      .then(() => {
105	        const logger = logs.getLogger(SERVICE_NAME);
106	        const logRecord: LogRecord = {
107	          body: event.toLogBody(),
