131	export function logToolCall(config: Config, event: ToolCallEvent): void {
132	  // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
133	  const uiEvent = {
134	    ...event,
135	    'event.name': EVENT_TOOL_CALL,
136	    'event.timestamp': new Date().toISOString(),
137	  } as UiEvent;
138	  uiTelemetryService.addEvent(uiEvent);
139	  ClearcutLogger.getInstance(config)?.logToolCallEvent(event);
140	  bufferTelemetryEvent(() => {
141	    const logger = logs.getLogger(SERVICE_NAME);
142	    const logRecord: LogRecord = {
143	      body: event.toLogBody(),
144	      attributes: event.toOpenTelemetryAttributes(config),
145	    };
146	    logger.emit(logRecord);
147	    recordToolCallMetrics(config, event.duration_ms, {
148	      function_name: event.function_name,
149	      success: event.success,
150	      decision: event.decision,
151	      tool_type: event.tool_type,
152	    });
153	
154	    if (event.metadata) {
155	      // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment
156	      const added = event.metadata['model_added_lines'];
157	      if (typeof added === 'number' && added > 0) {
158	        recordLinesChanged(config, added, 'added', {
159	          function_name: event.function_name,
160	        });
161	      }
162	      // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment
163	      const removed = event.metadata['model_removed_lines'];
164	      if (typeof removed === 'number' && removed > 0) {
165	        recordLinesChanged(config, removed, 'removed', {
166	          function_name: event.function_name,
167	        });
168	      }
169	    }
170	  });
171	}
