169	 * Determine the surface that the user is currently using.  Surface is effectively the
170	 * distribution channel in which the user is using Gemini CLI.  Gemini CLI comes bundled
171	 * w/ Firebase Studio and Cloud Shell.  Users that manually download themselves will
172	 * likely be "SURFACE_NOT_SET".
173	 *
174	 * This is computed based upon a series of environment variables these distribution
175	 * methods might have in their runtimes.
176	 */
177	function determineSurface(): string {
178	  if (process.env['SURFACE']) {
179	    return process.env['SURFACE'];
180	  } else if (isCloudShell()) {
181	    return IDE_DEFINITIONS.cloudshell.name;
182	  } else if (process.env['GITHUB_SHA']) {
183	    return 'GitHub';
184	  } else if (process.env['TERM_PROGRAM'] === 'vscode') {
185	    return detectIdeFromEnv().name || IDE_DEFINITIONS.vscode.name;
186	  } else {
187	    return 'SURFACE_NOT_SET';
188	  }
189	}
